//screen reso
var winwd = 0;
var winht = 0;
var tmpid;
var startDate = new Date(1999, 11, 11, 11, 11, 11);
var startTsp = startDate.getTime();
var endDate = new Date(2019, 8, 8, 11, 11, 11);
var endTsp = endDate.getTime();

import popup from "../../component/popup/popup";

export default {
  data() {
    return {
      currentTab: 0,
      user_openId: 'AAA',
      tuanCurrent: 0,
      tuanTarget: 700,
      ratio: 60 * 0 / 700,
      showTime: "",
      loopadsHT: "",
      loopadsWD: "",
      scrollHeight: "",
      initCardPos: "",
      cardHeight: "",
      loopimgs1: "",
      goods: "",
      cata: ""
    };
  },

  components: {
    popup
  },
  props: {},
  onReady: function () {
    //获得popup组件
    this.popup = this.selectComponent("#popup");
  },
  onPullDownRefresh: function () {
    wx.stopPullDownRefresh();
  },
  onLoad: function () {
    //timer
    var that = this;
    startDate = new Date();
    startTsp = startDate.getTime();
    var timer = setInterval(function () {
      startTsp += 1000;
      var diff = endTsp - startTsp;

      if (diff <= 0) {
        diff = 0;
        that.setData({
          showTime: {
            day: 0,
            hour: 0,
            minute: 0,
            second: 0
          }
        });
      }

      console.log(diff);
      that.setData({
        showTime: {
          day: parseInt(diff / (86400 * 1000)),
          hour: parseInt(diff % (86400 * 1000) / (1000 * 3600)),
          minute: parseInt(diff % (3600 * 1000) / (1000 * 60)),
          second: parseInt(diff % (60 * 1000) / 1000)
        }
      });

      if (diff <= 0) {
        clearInterval(timer);
      }
    }, 1000);
    tmpid = wx.getStorageSync('shopid');
    console.log(tmpid); //get user's screen reso

    wx.getSystemInfo({
      success: function (res) {
        winwd = res.windowWidth;
        winht = res.windowHeight;
      }
    });
    this.setData({
      //screen reso
      loopadsHT: winht * 0.3,
      loopadsWD: winwd,
      scrollHeight: winht * 0.64,
      initCardPos: winht * 0.36,
      cardHeight: winht * 0.64 * 0.6
    });
    uni.request({
    	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getdatawithkey',
    	method:'POST',
      data: {
        dbname: "StoreAds",
        shopId: tmpid
      },
      success: function (res) {
        that.setData({
          loopimgs1: res.data.Items[0].contents
        });
      }
    });
    uni.request({
    	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getdatawithkey',
    	method:'POST',
      data: {
        dbname: "items",
        shopId: tmpid
      },
      success: function (res) {
        that.setData({
          goods: res.data.Items[0].contents
        });
      }
    });
    uni.request({
    	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getfromdb',
    	method:'POST',
      data: {
        mode: 1,
        target: "shops",
        iddd: tmpid
      },
      success: function (res) {
        console.log(res.result[0]);
        endDate = new Date(res.result[0].tuanEnd);
        endTsp = res.result[0].tuanEnd;
        that.setData({
          cata: res.result[0].catagory,
          tuanTarget: res.result[0].tuanTarget,
          tuanCurrent: res.result[0].tuanCurrent,
          ratio: 60 * res.result[0].tuanCurrent / res.result[0].tuanTarget
        });
        console.log('ratio is: ' + that.ratio);
      },
      fail: function (res) {
        console.log(res);
      }
    });
  },
  methods: {
    showPopup() {
      this.popup.showPopup();
    },

    //取消事件
    _error() {
      console.log('你点击了取消');
      this.popup.hidePopup();
    },

    //确认事件
    _success() {
      console.log('你点击了确定');
      this.popup.hidePopup();
    },

    tapCart: function (e) {
      wx.navigateTo({
        url: '../pays/pay'
      });
    },
    clickTab: function (e) {
      var that = this;

      if (this.currentTab === e.target.dataset.current) {
        return false;
      } else {
        that.setData({
          currentTab: e.target.dataset.current
        });
      }

      console.log(this.currentTab);
    },
    stopTouchMove: function () {
      return false;
    },
    clickItem: function (e) {
      console.log(e.currentTarget.dataset.itemid);
      wx.setStorageSync("itemId", e.currentTarget.dataset.itemid);
      wx.setStorageSync("shopid", tmpid); //var tmp=wx.getStorageSync('shopid');

      wx.navigateTo({
        url: '../item/item'
      });
    },
    addtoCart: function (e) {
      //show popup
      this.showPopup();
      var that = this;
      uni.request({
      	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/pullcarts',
      	method:'POST',
        data: {
          dbname: "carts",
         openId: getApp().globalData.openId
        },
        success: function (res) {
          console.log(res);

          if (res.data.Items.length == 0) {
            //userUsingCartFirstTime
            uni.request({
            	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/initcart',
            	method:'POST',
              data: {
                shop_Id: tmpid,
				openId: getApp().globalData.openId,
              },
              success: function (res) {
                var itemLis = []; //same store

                uni.request({
                	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getitemid',
                	method:'POST',
                  data: {
                    itemId: e.target.dataset.itemid,
                    mode: 0
                  },
                  success: function (res) {
                    console.log('as1'); //check store

                    var i = 0;
                    var coun = 1;
                    var pos = 0;

                    for (i = 0; i < itemLis.length; i++) {
                      if (res.data.Items[0]._id == itemLis[i].Item_Id) {
                        coun = itemLis[i].count + 1;
                        pos = i;
                      }
                    }

                    if (coun == 1) {
                      itemLis.push({
                        Item_Id: res.data.Items[0]._id,
                        size: 'Large',
                        count: 1
                      });
                    } else {
                      itemLis[pos].count = coun;
                    }

                    uni.request({
                    	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/updatecartitem',
                    	method:'POST',
                      data: {
                        openId: getApp().globalData.openId,
                        itemList: itemLis,
                        sid: tmpid
                      },
                      success: function (res) {
                        console.log('succ');

                        that._success();
                      },
                      fail: console.error
                    });
                  }
                });
              }
            });
          } else {
            var itemLis = res.data.Items[0].items;
            console.log(itemLis);

            if (tmpid == res.data.Items[0].shop_Id) {
              //same store
              uni.request({
              	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getitemid',
              	method:'POST',
                data: {
                  itemId: e.target.dataset.itemid,
                  mode: 0
                },
                success: function (res) {
                  console.log('as1'); //check store

                  var i = 0;
                  var coun = 1;
                  var pos = 0;

                  for (i = 0; i < itemLis.length; i++) {
                    if (res.data.Items[0]._id == itemLis[i].Item_Id) {
                      coun = itemLis[i].count + 1;
                      pos = i;
                    }
                  }

                  if (coun == 1) {
                    itemLis.push({
                      Item_Id: res.data.Items[0]._id,
                      size: 'Large',
                      count: 1
                    });
                  } else {
                    itemLis[pos].count = coun;
                  }

                  uni.request({
                  	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/updatecartitem',
                  	method:'POST',
                    data: {
                      openId: getApp().globalData.openId,
                      itemList: itemLis,
                      sid: tmpid
                    },
                    success: function (res) {
                      console.log('succ');

                      that._success();
                    },
                    fail: console.error
                  });
                }
              });
            } else {
              //diff store
              //get item info
              uni.request({
              	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getitemid',
              	method:'POST',
                data: {
                  itemId: e.target.dataset.itemid,
                  mode: 0
                },
                success: function (res) {
                  console.log(res.result); //check store

                  uni.request({
                  	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/updatecartitem',
                  	method:'POST',
                    data: {
                      openId: getApp().globalData.openId,
                      itemList: [{
                        Item_Id: res.data.Items[0]._id,
                        size: 'Large',
                        count: 1
                      }],
                      sid: tmpid
                    },
                    success: function (res) {
                      console.log('succ');

                      that._success();
                    },
                    fail: console.error
                  });
                }
              });
            }
          }
        },
        fail: console.error
      });
    },
    setData: function (obj, callback) {
      let that = this;
      let keys = [];
      let val, data;
      Object.keys(obj).forEach(function (key) {
        keys = key.split('.');
        val = obj[key];
        data = that.$data;
        keys.forEach(function (key2, index) {
          if (index + 1 == keys.length) {
            that.$set(data, key2, val);
          } else {
            if (!data[key2]) {
              that.$set(data, key2, {});
            }
          }

          data = data[key2];
        });
      });
      callback && callback();
    }
  }
};
